bool objectShape(JsonVariantConst value, size_t members) {
  return value.is<JsonObjectConst>() && value.as<JsonObjectConst>().size() == members;
}

// Numeric strings, booleans, fractional integers and narrowing overflows are rejected.
bool unsignedValue(JsonVariantConst value, uint32_t maximum, uint32_t& result) {
  if (!value.is<uint32_t>()) return false;
  result = value.as<uint32_t>();
  return result <= maximum;
}

bool floatValue(JsonVariantConst value, float& result) {
  if (!value.is<float>()) return false;
  result = value.as<float>();
  return std::isfinite(result);
}

// Accept only four decimal octets, excluding ambiguous leading-zero spellings.
bool parseIp(JsonVariantConst value, uint8_t* ip) {
  if (!value.is<const char*>()) return false;
  const char* text = value.as<const char*>();
  size_t position = 0;
  for (unsigned part = 0; part < 4; part++) {
    unsigned octet = 0, digits = 0;
    bool leadingZero = text[position] == '0';
    while (position < 15 && text[position] >= '0' && text[position] <= '9') {
      octet = octet * 10 + unsigned(text[position++] - '0');
      if (++digits > 3 || octet > 255) return false;
    }
    if (!digits || (leadingZero && digits > 1)) return false;
    ip[part] = uint8_t(octet);
    if (part < 3) {
      if (position >= 15 || text[position++] != '.') return false;
    } else if (text[position] != '\0') return false;
  }
  return true;
}

// Read bounded controller fields before checking cross-controller invariants.
bool readController(JsonVariantConst source, Controller& controller) {
  uint32_t id, leds;
  if (!objectShape(source, 3) || !unsignedValue(source["id"], UINT16_MAX, id) || !unsignedValue(source["leds"], MAX_OUTPUT_LEDS, leds) || !parseIp(source["ip"], controller.ip)) return false;
  controller.id = uint16_t(id);
  controller.leds = uint16_t(leds);
  return true;
}

// Parse the complete physical interval and geometric endpoints without coercion.
bool readStrip(JsonVariantConst source, Strip& strip) {
  uint32_t id, controller, start, count;
  if (!objectShape(source, 9) || !unsignedValue(source["id"], UINT16_MAX, id) || !unsignedValue(source["controller"], UINT16_MAX, controller) || !unsignedValue(source["start"], MAX_OUTPUT_LEDS, start) || !unsignedValue(source["count"], MAX_OUTPUT_LEDS, count) || !source["reverse"].is<bool>() || !floatValue(source["x1"], strip.x1) || !floatValue(source["y1"], strip.y1) || !floatValue(source["x2"], strip.x2) || !floatValue(source["y2"], strip.y2)) return false;
  strip.id = uint16_t(id);
  strip.controller = uint16_t(controller);
  strip.start = uint16_t(start);
  strip.count = uint16_t(count);
  strip.reverse = source["reverse"].as<bool>();
  return true;
}

