bool parseConfig(JsonVariantConst root, Config& config, const char*& error) {
  Config candidate;
  error = "Invalid configuration structure or field type";
  uint32_t version, fps, brightness, seed;
  if (!objectShape(root, 8) || !unsignedValue(root["version"], UINT16_MAX, version) || !root["enabled"].is<bool>() || !unsignedValue(root["fps"], 60, fps) || !unsignedValue(root["brightness"], 255, brightness)) return false;
  candidate.version = uint16_t(version);
  candidate.enabled = root["enabled"].as<bool>();
  candidate.fps = uint8_t(fps);
  candidate.brightness = uint8_t(brightness);
  JsonVariantConst canvas = root["canvas"], effect = root["effect"];
  if (!objectShape(canvas, 2) || !floatValue(canvas["width"], candidate.canvas.width) || !floatValue(canvas["height"], candidate.canvas.height) || !objectShape(effect, 7) || !effect["name"].is<const char*>() || !parseEffectName(effect["name"].as<const char*>(), candidate.effect.type) || !unsignedValue(effect["seed"], UINT32_MAX, seed) || !floatValue(effect["speed"], candidate.effect.speed) || !floatValue(effect["wavelength"], candidate.effect.wavelength) || !floatValue(effect["direction"], candidate.effect.direction) || !floatValue(effect["centerX"], candidate.effect.centerX) || !floatValue(effect["centerY"], candidate.effect.centerY)) return false;
  candidate.effect.seed = seed;
  if (!root["controllers"].is<JsonArrayConst>() || !root["strips"].is<JsonArrayConst>()) return false;
  JsonArrayConst controllers = root["controllers"], strips = root["strips"];
  if (controllers.size() > MAX_CONTROLLERS || strips.size() > MAX_STRIPS) { error = "Controller or strip capacity exceeded"; return false; }
  for (JsonVariantConst source : controllers) {
    if (!readController(source, candidate.controllers[candidate.controllerCount])) return false;
    candidate.controllerCount++;
  }
  for (JsonVariantConst source : strips) {
    if (!readStrip(source, candidate.strips[candidate.stripCount])) return false;
    candidate.stripCount++;
  }
  if (!validateConfig(candidate, error)) return false;
  config = candidate;
  return true;
}

